# region: shape
def shape(raw):
    out = []
    for tok in raw:
        try:
            out.append(float(tok))
        except ValueError:
            pass
    return out

# region: digest
def digest(xs, offset=4):
    return [v - offset for v in xs]

# region: render
def render(xs):
    return [v * v for v in xs]

# region: intake
def intake(xs):
    return {'n': len(xs), 'total': sum(xs)}

# region: fold
def fold(summary):
    out = dict(summary)
    out['flags'] = sorted(k for k, v in summary.items() if isinstance(v, int) and v > 0)
    return out

# region: run
def run(raw):
    return fold(intake(render(digest(shape(raw)))))

